/**
 * New / edit a MANUAL task — work a person is given rather than work a workflow
 * produced.
 *
 * Everything else in this module refuses to hand-assign: `workflow_role_tasks`
 * is generated by the pinned path, owned by a role, and closing one advances the
 * item. That stays true. This modal writes a different row entirely
 * (`mos_manual_tasks`) for the coordination work no path models — «اعرضي حملة
 * مينا ٥٢ يوم الأحد», «جهّزي عرض المحتوى الشهري».
 *
 * Two rules the form makes visible rather than silent:
 *   - Assigning to SOMEONE ELSE needs the `assign_task` capability. Without it
 *     the person picker is replaced by a plain statement that the task is for
 *     you — never a dropdown that fails on save.
 *   - A repeating task is a RULE, not a row. The footer says in words what the
 *     rule will produce, and editing the rule regenerates the occurrences that
 *     have not started yet (the done ones are history and stay).
 */
import { useEffect, useMemo, useState } from 'react';
import { useAppStore } from '@/stores/appStore';
import {
  MosCampaign,
  MosContentRow,
  MosGoal,
  MosManualTask,
  MosRepeatRule,
  MosTaskSeries,
  fetchCampaigns,
  fetchContentList,
  fetchGoals,
  saveManualTask,
} from '@/lib/marketingOS/client';
import { useWorkspace } from '../MarketingWorkspace';
import { Field, Modal } from './kit';
import { num, shortDate } from '../lib/format';

/** Postgres DOW order, Sunday first — the Saudi work week starts on Sunday. */
const WEEKDAYS: Array<{ dow: number; ar: string; en: string }> = [
  { dow: 0, ar: 'الأحد', en: 'Sun' },
  { dow: 1, ar: 'الاثنين', en: 'Mon' },
  { dow: 2, ar: 'الثلاثاء', en: 'Tue' },
  { dow: 3, ar: 'الأربعاء', en: 'Wed' },
  { dow: 4, ar: 'الخميس', en: 'Thu' },
  { dow: 5, ar: 'الجمعة', en: 'Fri' },
  { dow: 6, ar: 'السبت', en: 'Sat' },
];

type Repeat = 'none' | 'daily' | 'weekly' | 'monthly';

/** Today in Riyadh as YYYY-MM-DD — the same anchor the server materializer uses. */
const riyadhToday = (): string =>
  new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh' }).format(new Date());

/** `2026-08-12T14:30` for a datetime-local input, from an ISO instant. */
function toLocalInput(iso: string | null): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number): string => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export default function NewTaskModal({
  onClose, onSaved, task, series, presetCampaign, presetContent, presetGoal, presetProject,
}: {
  onClose: () => void;
  onSaved?: () => void;
  /** Editing ONE task (a one-off, or a single occurrence of a series). */
  task?: MosManualTask | null;
  /** Editing the RULE behind a repeating task. */
  series?: MosTaskSeries | null;
  presetCampaign?: string | null;
  presetContent?: string | null;
  presetGoal?: string | null;
  presetProject?: string | null;
}) {
  const { people, projects, projectName, isAr, can, appUserId } = useWorkspace();
  const addToast = useAppStore((s) => s.addToast);
  const mayAssignOthers = can('assign_task');

  const source = series ?? task ?? null;

  const [title, setTitle] = useState(source?.title ?? '');
  const [details, setDetails] = useState(source?.details ?? '');
  const [assignee, setAssignee] = useState(
    source?.assignee_user_id ?? appUserId ?? '',
  );
  const [dueLocal, setDueLocal] = useState(toLocalInput(task?.due_at ?? null));
  const [campaignId, setCampaignId] = useState(source?.campaign_id ?? presetCampaign ?? '');
  const [contentId, setContentId] = useState(source?.content_id ?? presetContent ?? '');
  const [goalId, setGoalId] = useState(source?.goal_id ?? presetGoal ?? '');
  const [projectId, setProjectId] = useState(source?.project_id ?? presetProject ?? '');

  const [repeat, setRepeat] = useState<Repeat>(series ? series.freq : 'none');
  const [intervalN, setIntervalN] = useState(series?.interval_n ?? 1);
  const [byweekday, setByweekday] = useState<number[]>(series?.byweekday ?? []);
  const [bymonthday, setBymonthday] = useState(series?.bymonthday ?? 1);
  const [dueTime, setDueTime] = useState(series?.due_time?.slice(0, 5) ?? '10:00');
  const [startsOn, setStartsOn] = useState(series?.starts_on ?? riyadhToday());
  const [endsOn, setEndsOn] = useState(series?.ends_on ?? '');

  const [campaigns, setCampaigns] = useState<MosCampaign[]>([]);
  const [goals, setGoals] = useState<MosGoal[]>([]);
  const [content, setContent] = useState<MosContentRow[]>([]);
  const [busy, setBusy] = useState(false);

  // A task can hang off a campaign, a content item, a goal or a project. The
  // pickers are optional context, so a failed load degrades to "no options"
  // with a visible toast rather than blocking the save.
  useEffect(() => {
    void (async () => {
      try {
        const [c, g, k] = await Promise.all([
          fetchCampaigns(),
          fetchGoals(),
          fetchContentList({ limit: 300 }),
        ]);
        setCampaigns(c.campaigns);
        setGoals(g.goals);
        setContent(k.content);
      } catch (e) {
        console.error('[marketing] task link options unavailable', e);
        addToast(
          isAr ? 'تعذّر تحميل قوائم الربط — يمكن حفظ المهمة بدونها.' : 'Could not load the link options — the task still saves without them.',
          'error',
        );
      }
    })();
  }, [addToast, isAr]);

  const personName = (userId: string): string => {
    const p = people.find((x) => x.user_id === userId);
    if (!p) return isAr ? 'غير معروف' : 'unknown';
    return (isAr ? p.name_ar ?? p.name_en : p.name_en ?? p.name_ar) ?? p.email ?? userId.slice(0, 8);
  };

  const toggleDay = (dow: number): void =>
    setByweekday((cur) => (cur.includes(dow) ? cur.filter((d) => d !== dow) : [...cur, dow].sort()));

  /** The rule in words — what the footer promises the save will produce. */
  const rulePreview = useMemo((): string => {
    if (repeat === 'none') {
      if (!dueLocal) return isAr ? 'مهمة واحدة بلا موعد.' : 'A single task with no due date.';
      return isAr
        ? `مهمة واحدة، الاستحقاق ${shortDate(new Date(dueLocal).toISOString(), true)}.`
        : `A single task, due ${shortDate(new Date(dueLocal).toISOString(), false)}.`;
    }
    const every = intervalN === 1
      ? (isAr ? 'كل' : 'every')
      : (isAr ? `كل ${num(intervalN, true)}` : `every ${intervalN}`);
    let body: string;
    if (repeat === 'daily') {
      body = isAr ? `${every} ${intervalN === 1 ? 'يوم' : 'أيام'}` : `${every} day${intervalN === 1 ? '' : 's'}`;
    } else if (repeat === 'weekly') {
      const days = byweekday
        .map((d) => WEEKDAYS.find((w) => w.dow === d))
        .filter((w): w is (typeof WEEKDAYS)[number] => Boolean(w))
        .map((w) => (isAr ? w.ar : w.en))
        .join(isAr ? ' و' : ', ');
      if (!days) return isAr ? 'اختاري يومًا واحدًا على الأقل.' : 'Pick at least one weekday.';
      body = isAr
        ? `${every} ${intervalN === 1 ? 'أسبوع' : 'أسابيع'} — ${days}`
        : `${every} week${intervalN === 1 ? '' : 's'} on ${days}`;
    } else {
      body = isAr
        ? `${every} ${intervalN === 1 ? 'شهر' : 'أشهر'} — يوم ${num(bymonthday, true)}`
        : `${every} month${intervalN === 1 ? '' : 's'} on day ${bymonthday}`;
    }
    const who = assignee ? personName(assignee) : '';
    return isAr
      ? `${body}، الساعة ${dueTime} — تفتح تلقائيًا في مهام ${who}.`
      : `${body} at ${dueTime} — opens automatically in ${who}'s queue.`;
  }, [repeat, intervalN, byweekday, bymonthday, dueTime, dueLocal, assignee, isAr, people]);

  const submit = async (): Promise<void> => {
    if (!title.trim()) {
      addToast(isAr ? 'اكتبي عنوان المهمة.' : 'Give the task a title.', 'error');
      return;
    }
    if (repeat === 'weekly' && byweekday.length === 0) {
      addToast(
        isAr ? 'التكرار الأسبوعي يحتاج يومًا واحدًا على الأقل.' : 'A weekly repeat needs at least one weekday.',
        'error',
      );
      return;
    }
    setBusy(true);
    try {
      const rule: MosRepeatRule | null = repeat === 'none' ? null : {
        freq: repeat,
        interval_n: intervalN,
        byweekday: repeat === 'weekly' ? byweekday : [],
        bymonthday: repeat === 'monthly' ? bymonthday : null,
        due_time: dueTime,
        starts_on: startsOn,
        ends_on: endsOn || null,
      };
      await saveManualTask({
        ...(task && repeat === 'none' ? { id: task.id } : {}),
        ...(series ? { series_id: series.id } : {}),
        title: title.trim(),
        details: details.trim() || null,
        assignee_user_id: mayAssignOthers ? assignee : (appUserId ?? assignee),
        due_at: repeat === 'none' && dueLocal ? new Date(dueLocal).toISOString() : null,
        campaign_id: campaignId || null,
        content_id: contentId || null,
        goal_id: goalId || null,
        project_id: projectId || null,
        repeat: rule,
      });
      addToast(
        isAr
          ? (repeat === 'none' ? 'أُسندت المهمة.' : 'حُفظت المهمة المتكررة.')
          : (repeat === 'none' ? 'Task assigned.' : 'Repeating task saved.'),
        'success',
      );
      onClose();
      onSaved?.();
    } catch (e) {
      addToast(e instanceof Error ? e.message : String(e), 'error');
    } finally {
      setBusy(false);
    }
  };

  const editing = Boolean(task ?? series);

  return (
    <Modal
      title={editing
        ? (isAr ? 'تعديل المهمة' : 'Edit task')
        : (isAr ? 'مهمة جديدة' : 'New task')}
      sub={isAr
        ? 'مهمة تُسند بيدك — لا ينشئها مسار عمل، ولا تُحرّك أي مرحلة عند إنهائها.'
        : 'A task you assign by hand — no workflow creates it, and closing it advances nothing.'}
      onClose={onClose}
      footer={
        <>
          <span className="note">{rulePreview}</span>
          <button type="button" className="btn" onClick={onClose} disabled={busy}>
            {isAr ? 'إلغاء' : 'Cancel'}
          </button>
          <button type="button" className="btn btn-p" onClick={() => void submit()} disabled={busy}>
            {busy
              ? (isAr ? 'جارٍ الحفظ…' : 'Saving…')
              : editing
                ? (isAr ? 'حفظ' : 'Save')
                : (isAr ? 'إسناد' : 'Assign')}
          </button>
        </>
      }
    >
      <Field label={isAr ? 'المهمة' : 'Task'}>
        <input
          className="inp"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder={isAr ? 'مثال: اعرضي حملة مينا ٥٢ على الإدارة' : 'e.g. Present the Mina 52 campaign'}
          autoFocus
        />
      </Field>

      <Field label={isAr ? 'التفاصيل' : 'Details'} hint={isAr ? 'اختياري' : 'optional'}>
        <textarea
          className="inp"
          rows={3}
          value={details}
          onChange={(e) => setDetails(e.target.value)}
          placeholder={isAr ? 'ما المطلوب بالضبط؟' : 'What exactly is needed?'}
        />
      </Field>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 13 }}>
        <Field
          label={isAr ? 'المسؤول' : 'Assigned to'}
          hint={mayAssignOthers ? undefined : (isAr ? 'لكِ' : 'yourself')}
        >
          {mayAssignOthers ? (
            <select className="inp" value={assignee} onChange={(e) => setAssignee(e.target.value)}>
              {people.map((p) => (
                <option key={p.user_id} value={p.user_id}>{personName(p.user_id)}</option>
              ))}
            </select>
          ) : (
            // Not a disabled dropdown: the honest statement, so nobody picks a
            // name the save would refuse.
            <div className="inp" style={{ display: 'flex', alignItems: 'center', color: 'var(--mute)' }}>
              {isAr
                ? `${appUserId ? personName(appUserId) : ''} — إسناد المهام لغيركِ يحتاج صلاحية`
                : `${appUserId ? personName(appUserId) : ''} — assigning to others needs permission`}
            </div>
          )}
        </Field>

        {repeat === 'none' ? (
          <Field label={isAr ? 'الاستحقاق' : 'Due'} hint={isAr ? 'اختياري' : 'optional'}>
            <input
              type="datetime-local"
              className="inp"
              value={dueLocal}
              onChange={(e) => setDueLocal(e.target.value)}
            />
          </Field>
        ) : (
          <Field label={isAr ? 'وقت الاستحقاق' : 'Due time'} hint={isAr ? 'بتوقيت الرياض' : 'Riyadh time'}>
            <input
              type="time"
              className="inp"
              value={dueTime}
              onChange={(e) => setDueTime(e.target.value)}
            />
          </Field>
        )}
      </div>

      <div>
        <div className="lbl" style={{ marginBottom: 7 }}>{isAr ? 'التكرار' : 'Repeat'}</div>
        <div className="seg" style={{ width: '100%' }}>
          {(['none', 'daily', 'weekly', 'monthly'] as const).map((r) => (
            <button
              key={r}
              type="button"
              className={repeat === r ? 'on' : ''}
              style={{ flex: 1, textAlign: 'center' }}
              // Editing a single occurrence must not silently turn it into a
              // rule — the repeat control is only offered on create, or when
              // the rule itself is what is being edited.
              disabled={Boolean(task) && !series}
              onClick={() => setRepeat(r)}
            >
              {r === 'none' ? (isAr ? 'مرة واحدة' : 'Once')
                : r === 'daily' ? (isAr ? 'يومي' : 'Daily')
                : r === 'weekly' ? (isAr ? 'أسبوعي' : 'Weekly')
                : (isAr ? 'شهري' : 'Monthly')}
            </button>
          ))}
        </div>
      </div>

      {repeat !== 'none' && (
        <>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 13 }}>
            <Field label={isAr ? 'كل' : 'Every'}>
              <input
                type="number"
                min={1}
                max={52}
                className="inp"
                value={intervalN}
                onChange={(e) => setIntervalN(Math.max(1, Math.min(52, Number(e.target.value) || 1)))}
              />
            </Field>
            <Field label={isAr ? 'يبدأ في' : 'Starts'}>
              <input type="date" className="inp" value={startsOn} onChange={(e) => setStartsOn(e.target.value)} />
            </Field>
            <Field label={isAr ? 'ينتهي في' : 'Ends'} hint={isAr ? 'اختياري' : 'optional'}>
              <input type="date" className="inp" value={endsOn} onChange={(e) => setEndsOn(e.target.value)} />
            </Field>
          </div>

          {repeat === 'weekly' && (
            <div>
              <div className="lbl" style={{ marginBottom: 7 }}>{isAr ? 'أيام الأسبوع' : 'Weekdays'}</div>
              <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap' }}>
                {WEEKDAYS.map((w) => (
                  <button
                    key={w.dow}
                    type="button"
                    className={`fbtn${byweekday.includes(w.dow) ? ' on' : ''}`}
                    onClick={() => toggleDay(w.dow)}
                  >
                    {isAr ? w.ar : w.en}
                  </button>
                ))}
              </div>
            </div>
          )}

          {repeat === 'monthly' && (
            <Field
              label={isAr ? 'يوم الشهر' : 'Day of the month'}
              hint={isAr ? '٣١ في شهر أقصر ينزل لآخر يوم فيه' : '31 in a shorter month falls on its last day'}
            >
              <input
                type="number"
                min={1}
                max={31}
                className="inp"
                value={bymonthday}
                onChange={(e) => setBymonthday(Math.max(1, Math.min(31, Number(e.target.value) || 1)))}
              />
            </Field>
          )}
        </>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 13 }}>
        <Field label={isAr ? 'الحملة' : 'Campaign'} hint={isAr ? 'اختياري' : 'optional'}>
          <select className="inp" value={campaignId} onChange={(e) => setCampaignId(e.target.value)}>
            <option value="">{isAr ? 'بدون' : 'None'}</option>
            {campaigns.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </Field>
        <Field label={isAr ? 'المحتوى' : 'Content'} hint={isAr ? 'اختياري' : 'optional'}>
          <select className="inp" value={contentId} onChange={(e) => setContentId(e.target.value)}>
            <option value="">{isAr ? 'بدون' : 'None'}</option>
            {content.map((c) => (
              <option key={c.id} value={c.id}>{c.ref ? `${c.ref} · ${c.title}` : c.title}</option>
            ))}
          </select>
        </Field>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 13 }}>
        <Field label={isAr ? 'الهدف' : 'Goal'} hint={isAr ? 'اختياري' : 'optional'}>
          <select className="inp" value={goalId} onChange={(e) => setGoalId(e.target.value)}>
            <option value="">{isAr ? 'بدون' : 'None'}</option>
            {goals.map((g) => <option key={g.id} value={g.id}>{g.name}</option>)}
          </select>
        </Field>
        <Field label={isAr ? 'المشروع' : 'Project'} hint={isAr ? 'اختياري' : 'optional'}>
          <select className="inp" value={projectId} onChange={(e) => setProjectId(e.target.value)}>
            <option value="">{isAr ? 'بدون' : 'None'}</option>
            {projects.map((p) => (
              <option key={p.id} value={p.id}>{projectName(p.id)}</option>
            ))}
          </select>
        </Field>
      </div>
    </Modal>
  );
}
